<?php declare(strict_types=1); namespace App\Services; use InvalidArgumentException;
final class DatabaseNativeClientCommandBuilder{public function build(string $operation,string $family,string $executable,string $defaults,string $database,string $charset):array{if(!in_array($operation,['backup','restore'],true)||!in_array($family,['mysql','mariadb'],true)||$executable===''||$defaults===''||$charset!=='utf8mb4'||preg_match('/[\0\r\n]/',$executable.$defaults.$database.$charset)||preg_match('/\s|[\\\\\/;=]/',$database))throw new InvalidArgumentException('Native database client command is invalid.');$a=['--defaults-extra-file='.$defaults];if($operation==='backup'){$a=array_merge($a,['--single-transaction','--quick','--skip-lock-tables']);if($family==='mysql')$a=array_merge($a,['--column-statistics=0','--no-tablespaces']);$a=array_merge($a,['--hex-blob','--default-character-set='.$charset]);}else $a[]='--default-character-set='.$charset;$a[]=$database;return ['executable'=>$executable,'arguments'=>$a,'operation'=>$operation,'family'=>$family];}}
